import{_ as t,o as e,c as n,a2 as o}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Tenant Domains & Per-Domain Settings","description":"Tenant subdomains, primary and secondary domains, and per-domain settings: app name, default language and which authentication features are enabled.","frontmatter":{"title":"Tenant Domains & Per-Domain Settings","description":"Tenant subdomains, primary and secondary domains, and per-domain settings: app name, default language and which authentication features are enabled.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/core/domains.html"}],["meta",{"property":"og:title","content":"Tenant Domains & Per-Domain Settings"}],["meta",{"property":"og:description","content":"Tenant subdomains, primary and secondary domains, and per-domain settings: app name, default language and which authentication features are enabled."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/core/domains.html"}],["meta",{"name":"twitter:title","content":"Tenant Domains & Per-Domain Settings"}],["meta",{"name":"twitter:description","content":"Tenant subdomains, primary and secondary domains, and per-domain settings: app name, default language and which authentication features are enabled."}]]},"headers":[],"relativePath":"docs/core/domains.md","filePath":"docs/core/domains.md","lastUpdated":1790486087000}'),d={name:"docs/core/domains.md"};function i(s,a,r,c,l,m){return e(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="domains" tabindex="-1">Domains <a class="header-anchor" href="#domains" aria-label="Permalink to &quot;Domains&quot;">​</a></h1><p>A domain is how a request finds its tenant. Each tenant has one or more domains, stored in the central <code>domains</code> table (<code>App\\Models\\Domain</code>), and every domain also carries its own branding, language and auth settings.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>acme.vue.test  → domains table → tenant 1 → per-domain App name, language, auth features</span></span></code></pre></div><h2 id="domain-format" tabindex="-1">Domain format <a class="header-anchor" href="#domain-format" aria-label="Permalink to &quot;Domain format&quot;">​</a></h2><p>Domains are <strong>subdomains of <code>APP_DOMAIN</code></strong>. You enter only the subdomain; the kit appends the central domain:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>input: acme      → stored: acme.vue.test</span></span>
<span class="line"><span>input: acme-eu   → stored: acme-eu.vue.test</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Rule</th><th>Value</th></tr></thead><tbody><tr><td>Characters</td><td>Lowercase letters, digits and single hyphens (<code>^[a-z0-9]+(?:-[a-z0-9]+)*$</code>)</td></tr><tr><td>Length</td><td>Max 63 characters</td></tr><tr><td>Uniqueness</td><td>Unique across all tenants (<code>UniqueTenantDomain</code> rule)</td></tr><tr><td>Validated by</td><td><code>TenantRegisterData</code> (new tenant), <code>DomainData</code> (extra domain)</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Custom top-level domains</p><p><code>DomainService::createDomain()</code> always builds <code>&lt;sub&gt;.APP_DOMAIN</code>. Mapping fully custom domains (e.g. <code>app.customer.com</code>) is not part of the kit.</p></div><h2 id="domains-page" tabindex="-1">Domains page <a class="header-anchor" href="#domains-page" aria-label="Permalink to &quot;Domains page&quot;">​</a></h2><p><code>/tenants/domains</code> lists all domains of all tenants. It is central only and needs <code>View Tenants</code>.</p><ul><li>Paginated, with stats cards</li><li>Search by domain or tenant, filter by <strong>primary</strong> / <strong>secondary</strong></li><li>Add, set primary, delete, settings and authentication features (require <code>Manage Tenant Domains</code>)</li></ul><p>The same actions are available per tenant on the tenant detail page.</p><table tabindex="0"><thead><tr><th>Action</th><th>Route</th></tr></thead><tbody><tr><td>Add domain</td><td><code>POST /tenants/domains</code></td></tr><tr><td>Set primary</td><td><code>PATCH /tenants/domains/{domain}/primary</code></td></tr><tr><td>Delete</td><td><code>DELETE /tenants/domains/{domain}</code></td></tr><tr><td>Settings (App name, language)</td><td><code>PUT /tenants/domains/{domain}/settings</code></td></tr><tr><td>Authentication features</td><td><code>PUT /tenants/domains/{domain}/auth-features</code></td></tr></tbody></table><h2 id="primary-domain" tabindex="-1">Primary domain <a class="header-anchor" href="#primary-domain" aria-label="Permalink to &quot;Primary domain&quot;">​</a></h2><p>Each tenant has exactly one primary domain. Invitation links and tenant links use it.</p><ul><li>The first domain of a tenant is always primary. Adding a domain with <strong>primary</strong> checked moves the flag.</li><li>The primary domain <strong>cannot be deleted</strong>. Make another domain primary first.</li></ul><h2 id="per-domain-settings" tabindex="-1">Per-domain settings <a class="header-anchor" href="#per-domain-settings" aria-label="Permalink to &quot;Per-domain settings&quot;">​</a></h2><p>Each domain can override three settings. They are stored as columns on <code>domains</code> and validated by <code>Modules\\Tenant\\Data\\DomainSettingsData</code> (auth features by their own request).</p><table tabindex="0"><thead><tr><th>Setting</th><th>Column</th><th>Effect</th></tr></thead><tbody><tr><td>App name</td><td><code>app_name</code> (max 100 chars)</td><td>Brand shown in the sidebar, auth pages, page titles and emails sent on that domain</td></tr><tr><td>Default language</td><td><code>locale</code></td><td>Default language for users on that domain who have not picked one</td></tr><tr><td>Authentication features</td><td><code>auth_features</code> (JSON)</td><td>Turns Fortify features on or off for that domain only</td></tr></tbody></table><h3 id="app-name" tabindex="-1">App name <a class="header-anchor" href="#app-name" aria-label="Permalink to &quot;App name&quot;">​</a></h3><p>When tenancy starts, <code>App\\Listeners\\ApplyTenantAppName</code> sets <code>config(&#39;app.name&#39;)</code> to the first value that exists:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>domain app_name → tenant company → central APP_NAME</span></span></code></pre></div><h3 id="default-language" tabindex="-1">Default language <a class="header-anchor" href="#default-language" aria-label="Permalink to &quot;Default language&quot;">​</a></h3><p>One of the 17 <code>LanguageEnum</code> values, or empty to use the app default. See <a href="/docs/core/localization.html#how-the-locale-is-resolved">Localization</a>.</p><h3 id="authentication-features" tabindex="-1">Authentication features <a class="header-anchor" href="#authentication-features" aria-label="Permalink to &quot;Authentication features&quot;">​</a></h3><p>Registration, password reset, email verification, two-factor and passkeys can be switched off per domain. See <a href="/docs/core/authentication.html#per-domain-features">Authentication → Per-domain features</a>.</p><h2 id="local-dns" tabindex="-1">Local DNS <a class="header-anchor" href="#local-dns" aria-label="Permalink to &quot;Local DNS&quot;">​</a></h2><p>Every tenant domain must resolve to your app.</p><table tabindex="0"><thead><tr><th>Environment</th><th>Setup</th></tr></thead><tbody><tr><td>Local with Herd</td><td>All <code>*.vue.test</code> subdomains work automatically once the site is linked</td></tr><tr><td>Production</td><td>A wildcard DNS record (<code>*.your-domain.com</code>) plus a wildcard virtual host and TLS certificate</td></tr></tbody></table>`,29)])])}const u=t(d,[["render",i]]);export{h as __pageData,u as default};
